const path = '/api/automation-events';
return $input.all().map(({ json: j }) => ({
  json: signForConvex('POST', path, JSON.stringify({
    idempotencyKey: j.reminderKey,          // overdue:<loanId>:<YYYY-MM-DD>
    loanId: j.loanId,
    kind: 'overdue_reminder',
